ruleToc.chapterList:
@js:
function chapterSorted(){
  const chapters = []
  let elements = java.getElements("li.BCsectionTwo-top-chapter")
  for(let i in elements){
    let li = String(elements[i].outerHtml())
    let title, url, id;
    id = String(java.getString("li@data-mm5", li)).trim()
    if(id){
      title = java.getString("a@data-mm3", li)
      url = java.getString("a@data-mm4", li)
    } else {
      id = java.getString("li@data-mm3", li)
      title = java.getString("a@data-mm4", li)
      url = java.getString("a@data-mm5", li)
    }
    url = java.base64Decode(url)
    chapters.push({id, title, url})
  }
  return chapters.sort((a, b) => a.id - b.id)
}

chapterSorted()

